import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useStore } from '@/store'
import { useRevision } from '@/hooks/useRevision'
import { signOut } from '@/hooks/useAuth'
import { TIPOS_TESIS, NORMAS } from '@/types'
import { relativeTime, cn } from '@/lib/utils'
import type { NormaType } from '@/types'
import type { LTMatch } from '@/hooks/useLanguageTool'
import ReferencesPanel    from '@/components/references/ReferencesPanel'
import RevisionPanel      from '@/components/revision/RevisionPanel'
import GrammarPanel       from '@/components/revision/GrammarPanel'
import ProgressPanel      from '@/components/revision/ProgressPanel'
import AcademicValidator  from '@/components/revision/AcademicValidator'

const LOGO_SRC = 'data:image/png;base64,'

type PanelTab = 'structure' | 'refs' | 'grammar' | 'progress' | 'academic'

interface SidebarProps {
  grammarMatches?: LTMatch[]
  activeSectionForGrammar?: string
}

export default function Sidebar({ grammarMatches = [], activeSectionForGrammar }: SidebarProps) {
  const navigate = useNavigate()
  const {
    project, sections, norma, setNorma,
    revisionIssues, isSaving, lastSaved,
    activeSectionId, setActiveSection,
  } = useStore()
  const { runRevision } = useRevision()
  const [tab, setTab] = useState<PanelTab>('structure')

  // Let the ribbon toolbar (Revisar / Referencias tabs) switch panels here
  useEffect(() => {
    const handler = (e: Event) => {
      const target = (e as CustomEvent).detail as PanelTab
      if (target) setTab(target)
    }
    window.addEventListener('switch-sidebar-tab', handler)
    return () => window.removeEventListener('switch-sidebar-tab', handler)
  }, [])

  const tipo           = project ? TIPOS_TESIS[project.tipo] : null
  const sectionByName  = new Map(sections.map(s => [s.name, s]))
  const totalWords     = sections.reduce((s, sec) => s + sec.word_count, 0)
  const totalSections  = tipo ? tipo.fases.reduce((acc, f) => acc + f.items.length, 0) : 0
  const filledSections = sections.filter(s => s.word_count > 0).length
  const progress       = totalSections ? Math.round(filledSections / totalSections * 100) : 0
  const grammarTotal   = grammarMatches.length

  const scrollToSection = (name: string) => {
    const sec = sectionByName.get(name)
    const id  = sec ? `section-${sec.id}` : `section-virtual-${name}`
    setActiveSection(sec?.id ?? `virtual-${name}`)
    const el = document.getElementById(id)
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' })
  }

  const handleFix = (match: LTMatch, replacement: string) => {
    window.dispatchEvent(new CustomEvent('apply-grammar-fix', {
      detail: { match, replacement, sectionId: activeSectionForGrammar }
    }))
  }

  return (
    <aside className="w-64 min-w-64 flex flex-col bg-gradient-to-b from-brand-900 to-brand-950 border-r border-white/10 overflow-hidden">

      {/* Brand */}
      <div className="flex items-center gap-2.5 px-3.5 py-3 border-b border-white/10 flex-shrink-0">
        <div className="w-9 h-9 rounded-lg bg-white/10 border border-white/15 flex items-center justify-center flex-shrink-0 overflow-hidden p-1">
          <img src={LOGO_SRC} alt="Graduate" className="w-full h-full object-contain" />
        </div>
        <div className="min-w-0">
          <div className="font-serif text-white text-base font-semibold leading-tight">
            Graduate{" "}
            <span className="text-xs bg-gold text-brand-950 rounded px-1 font-bold align-middle">PRO</span>
          </div>
          <div className="text-white/40 text-xs">by RonnDu Corp.</div>
        </div>
      </div>

      {/* Project + norma */}
      <div className="px-3.5 py-2.5 border-b border-white/10 flex-shrink-0 space-y-2">
        <button onClick={() => navigate("/")}
          className="flex items-center gap-1.5 text-white/60 hover:text-gold text-xs transition-colors w-full text-left">
          <i className="ti ti-chevron-left text-xs" />
          <span className="truncate">{project?.title ?? "Dashboard"}</span>
        </button>

        <div>
          <p className="text-white/35 text-xs mb-1 uppercase tracking-wider">Norma</p>
          <div className="flex gap-1">
            {(["libre","apa","vancouver"] as NormaType[]).map(n => (
              <button key={n} onClick={() => setNorma(n)}
                className={cn(
                  "flex-1 text-xs py-1 rounded-md border transition-all",
                  norma === n
                    ? "bg-gold text-brand-950 border-gold font-medium"
                    : "bg-white/5 text-white/60 border-white/10 hover:border-gold/60 hover:text-white"
                )}>
                {NORMAS[n].label}
              </button>
            ))}
          </div>
        </div>

        <div>
          <div className="flex justify-between text-xs text-white/50 mb-1">
            <span>{filledSections}/{totalSections} secciones</span>
            <span>{totalWords.toLocaleString("es")} palabras</span>
          </div>
          <div className="h-1.5 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-brand-300 to-gold transition-all duration-500 rounded-full"
              style={{ width: `${progress}%` }} />
          </div>
        </div>
      </div>

      {/* Tabs - 5 panels */}
      <div className="flex border-b border-white/10 flex-shrink-0">
        {([
          { id: "structure", icon: "ti-layout-list",      badge: 0 },
          { id: "refs",      icon: "ti-books",             badge: 0 },
          { id: "grammar",   icon: "ti-text-spellcheck",   badge: grammarTotal },
          { id: "progress",  icon: "ti-chart-bar",         badge: 0 },
          { id: "academic",  icon: "ti-clipboard-check",   badge: 0 },
        ] as const).map(t => (
          <button key={t.id}
            onClick={() => setTab(t.id as PanelTab)}
            className={cn(
              "flex-1 flex items-center justify-center py-2 text-sm border-b-2 transition-all relative",
              tab === t.id ? "text-gold border-gold" : "text-white/40 border-transparent hover:text-white/70"
            )}>
            <i className={`ti ${t.icon}`} />
            {t.badge > 0 && (
              <span className="absolute top-0.5 right-0.5 bg-red-500 text-white rounded-full w-3.5 h-3.5 flex items-center justify-center" style={{fontSize:"8px"}}>
                {t.badge > 9 ? "9+" : t.badge}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Panel content */}
      <div className="flex-1 overflow-y-auto sidebar-scroll">
        {tab === "structure" && tipo && (
          <div className="py-1">
            {tipo.fases.map(fase => (
              <div key={fase.fase}>
                <div className="px-3.5 pt-3 pb-1">
                  <p className="text-white/35 text-xs font-medium uppercase tracking-wider">
                    {fase.isRoman ? "(i,ii) " : "(1,2) "}{fase.fase}
                  </p>
                </div>
                {fase.items.map(name => {
                  const sec      = sectionByName.get(name)
                  const isActive = sec ? sec.id === activeSectionId : (`virtual-${name}` === activeSectionId)
                  const hasCont  = sec ? sec.word_count > 0 : false
                  return (
                    <button key={name} onClick={() => scrollToSection(name)}
                      className={cn(
                        "w-full flex items-start gap-2 px-3.5 py-1.5 text-left text-xs transition-all border-l-2",
                        isActive
                          ? "bg-gold/10 border-gold text-white"
                          : "border-transparent text-white/55 hover:bg-white/5 hover:text-white"
                      )}>
                      <span className={cn(
                        "w-1.5 h-1.5 rounded-full mt-1 flex-shrink-0",
                        isActive ? "bg-gold" : hasCont ? "bg-white/50" : "bg-white/15"
                      )} />
                      <span className="leading-tight">{name}</span>
                      {hasCont && (
                        <span className="ml-auto text-white/35 text-xs flex-shrink-0">{sec!.word_count}</span>
                      )}
                    </button>
                  )
                })}
              </div>
            ))}
          </div>
        )}
        {tab === "refs"     && <ReferencesPanel />}
        {tab === "grammar"  && <GrammarPanel matches={grammarMatches} checking={false} onFix={handleFix} onDismiss={() => {}} />}
        {tab === "progress" && <ProgressPanel />}
        {tab === "academic" && <AcademicValidator />}
      </div>

      {/* Status */}
      <div className="px-3.5 py-2 border-t border-white/10 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-1.5">
          <span className={cn("w-1.5 h-1.5 rounded-full", isSaving ? "bg-gold animate-pulse" : "bg-green-400")} />
          <span className="text-white/40 text-xs">
            {isSaving ? "Guardando..." : lastSaved ? relativeTime(lastSaved) : "Listo"}
          </span>
        </div>
        <button onClick={signOut} className="text-white/40 hover:text-gold text-xs transition-colors">
          <i className="ti ti-logout text-sm" />
        </button>
      </div>
    </aside>
  )
}
